document.addEventListener('change',e=>{const el=e.target;if(el.dataset.file){files[el.dataset.file]=el.files[0];updateFiles();updateFileField(el);if(files[el.dataset.file]){const f=files[el.dataset.file];errorAt('#upload-error',!/\.nii(\.gz)?$/i.test(f.name)?'Unsupported file. Choose a .nii or .nii.gz volume.':f.size>150*1024*1024?'This file exceeds the deployed 150 MB upload limit.':null);}}if(['opening','history-opening'].includes(el.name))setOpening(el.value);if(el.id==='modality'){modality=el.value;loadViewer();}if(el.id==='overlay'){overlay=el.value;loadViewer();}if(el.id==='attempt-select'){const next=structuredClone(review);next.active_attempt_id=el.value||null;saveDoc(next);}});

// ── Upload Page Visual Enhancements ────────────────────────────────────────

// Mark file-field zone with has-file class and show filename badge
function updateFileField(input) {
  const zone = input.closest('.file-field');
  if (!zone) return;
  const file = input.files[0];
  zone.classList.toggle('has-file', !!file);
  // Remove old badge
  zone.querySelector('.file-name')?.remove();
  if (file) {
    const badge = document.createElement('div');
    badge.className = 'file-name';
    badge.innerHTML = `<i data-lucide="check" class="icon"></i><span>${file.name} <em style="color:var(--text-muted);font-style:normal">(${(file.size/1024/1024).toFixed(2)} MB)</em></span>`;
    zone.appendChild(badge);
    icons();
  }
  updateSeqProgress();
}

// Sequence progress pips in sidebar
function updateSeqProgress() {
  const pips = $$('.seq-pip');
  ['t1','t1c','t2','flair'].forEach((k,i) => {
    if (pips[i]) pips[i].classList.toggle('filled', !!files[k]);
  });
}

// Init upload page specifics after DOM is ready
function initUploadPage() {
  // Add data-seq attribute to file-field wrappers (for CSS colour dots)
  ['t1','t1c','t2','flair'].forEach(seq => {
    const input = $(`#file-${seq}`);
    if (input) input.closest('.file-field')?.setAttribute('data-seq', seq);
  });

  // Add data-n (step number) attribute to .step spans for CSS counter badge
  $$('#page-upload .step').forEach((el, i) => el.setAttribute('data-n', String(i + 1)));

  // Inject seq-progress pips into sidebar card if not already present
  const countEl = $('#selected-count');
  if (countEl && !$('.seq-progress')) {
    const prog = document.createElement('div');
    prog.className = 'seq-progress';
    prog.innerHTML = '<div class="seq-pip"></div><div class="seq-pip"></div><div class="seq-pip"></div><div class="seq-pip"></div>';
    countEl.parentNode.insertBefore(prog, countEl.nextSibling);
  }

  // Drag and drop visual state on file-fields
  $$('.file-field').forEach(zone => {
    const input = zone.querySelector('input[type=file]');
    if (!input) return;
    zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('drag-over'); });
    zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'));
    zone.addEventListener('drop', e => {
      e.preventDefault();
      zone.classList.remove('drag-over');
      const file = e.dataTransfer.files[0];
      if (!file || !input.dataset.file) return;
      // Transfer to input via DataTransfer
      try {
        const dt = new DataTransfer();
        dt.items.add(file);
        input.files = dt.files;
        input.dispatchEvent(new Event('change', { bubbles: true }));
      } catch { /* fallback — browser doesn't support DataTransfer write */ }
    });
    // Make the whole zone clickable
    zone.addEventListener('click', e => { if (e.target !== input && !e.target.closest('input')) input.click(); });
  });
}

// Run upload page enhancements on navigation
window.addEventListener('hashchange', () => {
  if (location.hash.slice(1).split('?')[0] === 'upload') {
    requestAnimationFrame(initUploadPage);
  }
});
// Also run on first load if starting on upload
if (location.hash.slice(1).split('?')[0] === 'upload') {
  requestAnimationFrame(initUploadPage);
}
document.addEventListener('input',e=>{if(e.target.id==='opacity'){opacity=Number(e.target.value);viewer?.setOpacity(opacity);}if(e.target.dataset.mesh)viewer?.mesh(e.target.dataset.mesh,e.target.value);});
$('#faq-search').oninput=e=>{let count=0;$$('#faq-list details').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!el.hidden)count++;});$('#faq-empty').hidden=count>0;};
$('#settings-form').onsubmit=async e=>{e.preventDefault();const value=$('#backend-url').value.trim();try{if(value){const url=new URL(value);if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.pathname!=='/'||url.search||url.hash)throw new Error('Enter an HTTP(S) origin without a path, credentials or query.');if(location.protocol==='https:'&&url.protocol==='http:')throw new Error('Use HTTPS for a backend connected to this HTTPS page, or run the frontend locally.');}if(busy)throw new Error('Wait for the active job or retry its status before switching backends.');clearStudy();storage.removeItem('neuroscope:lastJob');storage.removeItem('neuroscope:pendingJob');api=new Api(value);storage.setItem('neuroscope:backend',value);$('#settings-dialog').close();await connect();toast(status?'Backend connected':'Backend unavailable. Check the address and CORS configuration.');}catch(error){errorAt('#settings-error',error);}};
window.addEventListener('hashchange',route);window.addEventListener('beforeprint',()=>{if(!allowed().report)$('#report-content').innerHTML=`<p>Report hidden by review permissions.</p>`;});window.addEventListener('afterprint',renderReport);
function positionNavPill(){const pill=$('.nav-pill');if(!pill)return;const activeLink=$('nav a.active');if(!activeLink){pill.style.opacity='0';return;}const nav=activeLink.parentElement;const navRect=nav.getBoundingClientRect();const linkRect=activeLink.getBoundingClientRect();pill.style.width=linkRect.width+'px';pill.style.left=(linkRect.left-navRect.left)+'px';pill.style.opacity='1';}
window.addEventListener('scroll',()=>{const header=$('header');if(!header)return;header.classList.toggle('scrolled',window.scrollY>30);},{passive:true});
function initScrollReveal(){const targets=$$('.scroll-reveal');if(!targets.length)return;const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});targets.forEach(el=>observer.observe(el));}
window.addEventListener('resize',positionNavPill);
renderModels();renderReport();route();connect().then(()=>{const saved=storage.getItem('neuroscope:pendingJob');if(saved){try{const j=JSON.parse(saved);setBusy(true);pollJob(j.id,j.opening);}catch{storage.removeItem('neuroscope:pendingJob');}}else{const id=storage.getItem('neuroscope:lastJob');if(id&&status)openJob(id,'normal');}});
